kills.mutated_unit_code:
function SetMinSum(uint _val)
    public
    {
        if(!intitalized) revert();
        MinSum = _val;
    }

function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        require(_val != 0);
        MinSum = _val;
    }

function SetMinSum(uint _val)
    public
    {
        if(intitalized)revert();
        MinSum = MinSum + _val;
    }

function SetLogFile(address _log)
    public
    {
        if(intitalized)revert();
        Log = LogFile(_log);
        intitalized = true;
    }
